using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class UgoFoscolo
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Che Dante non amasse l'Italia, chi vorrà dirlo? Anch'ei fu costretto, come qualunque altro l'ha mai veracemente amata, o mai l'amerà, a flagellarla a sangue, e mostrarle tutta la sua nudità, sì che ne senta vergogna.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Federigo II aspirava a riunire l'Italia sotto un solo principe, una sola forma di governo e una sola lingua; e tramandarla a' suoi successori potentissima fra le monarchie d'Europa [...].", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Gli errori umani, non ostante l'infinito lor numero, e la loro audacia naturale, e la loro ostinazione proveniente dall'ignoranza, cedono tosto o tardi alla voce del vero; bensì dove i governi e le sette sono interessate a sostenerli, anche gli errori degni di riso riescono formidabili e sacri, ogni qualvolta non sia libero il disputare contr'essi.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "gli schiavi non sono, generalmente parlando, fatti dai tiranni, ma bensì gli schiavi fanno i tiranni.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Gli scienziati sono per lo più cosmopoliti, perché le loro dottrine si esprimono per cifre e per segni d'alfabeto universale, e in guisa che sono intesi dagli scienziati di tutto il mondo, e si servono più di aritmetica che di eloquenza.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Il dolore in chi manca di pane è più rassegnato.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "il primo motore di tutte le azioni è la noia, la quale ci fa cercare occupazioni e desiderj nuovi, quando sono soddisfatti quelli che ci rodevano.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Il ridicolo poi non è arme contra la tirannia così potente come si suole stimarla, perocché una nazione avvezza a ridersi di tutte le cose è tale che un governo la può insultare colla maggior sicurezza.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "L'odio è la catena più grave insieme e più abietta, con la quale l'uomo possa legarsi all'uomo.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "L'opinione pubblica d'un popolo non si ritrova nelle abitudini, ne' pregiudizi, nelle teorie e nelle speranze d'una casta; anche meno nei sentimenti esaltati di alcuni cittadini, e nei delusi interessi di molti più, ma sì nell'umana natura, perciocché, date le medesime circostanze, si manifesta in tutti gli uomini, e sempre invariabile.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "la molta lettura riesce come una gran quantità di semenza stivata in poca terra: una parte vi germoglia e cresce a stento, impacciata dall'altra che rimane senza avere ottenuto i necessari umori per riprodursi.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La vendetta è una passione di natura ignea; se le darete luogo ed aria, si svapora e si spegne; se la comprimerete, andrà serpeggiando insidiosa e scoppierà col delitto e col tradimento.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Lo stile assoluto e sicuro del libro dei Delitti e delle Pene e l'elegante trattato del Galiani sulle Monete vivranno nobile ed eterno retaggio tra noi.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Non son chi fui.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "O Italiani, io vi esorto alle storie.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "quel poco di felicità che si può sperar sulla terra consiste nel piacere a sé stessi; al che stimo indispensabili due cose: l'una, di seguire fedelmente i proprj principj; l'altra, di potere liberamente esercitare le facoltà del cuore e dell'intelletto.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Qui la povertà è vergogna che nessun merito lava.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Te dunque, o Bonaparte, nomerò con inaudito titolo LIBERATORE DI POPOLI E FONDATORE DI REPUBBLICA. Così tu alto, solo, immortale, dominerai l'eternità, pari agli altri grandi nelle gesta e ne' meriti, ma a niuno comparabile nella intrapresa di fondare nazioni.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Una o due ingiurie virilmente sofferte, rimandano il vituperio su chi le fa; ma, ove le siano continue e continuamente dissimulate, il silenzio dell'innocenza è ascritto a coscienza di colpa, e l'alterezza del forte a viltà.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Una parte degli uomini opera senza pensare, l'altra pensa senza operare.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "A egregie cose il forte animo accendono | l'urne de' forti, o Pindemonte.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "A' generosi | giusta di gloria dispensiera è morte.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Anche la Speme, | ultima Dea, fugge i sepolcri; e involve | tutte cose l'obblio nella sua notte", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Celeste è questa | corrispondenza di amorosi sensi, | celeste dote è negli umani", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Sol chi non lascia eredità d'affetti | poca gioia ha dell'urna.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "E tu gli ornavi del tuo riso i canti | che il lombardo pungean Sardanapalo | cui solo è dolce il muggito de' buoi, | che dagli antri abdüani e dal Ticino | lo fan d'ozi beato e di vivande", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "E uscir del teschio, ove fuggìa la Luna, | l'upupa, e svolazzar su per le croci | sparse per la funerea campagna, | e l'immonda accusar col luttuoso | singulto i rai di che son pie le stelle | alle obblîate sepolture.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Ahi! sugli estinti | non sorge fiore, ove non sia d'umane | lodi onorato e d'amoroso pianto", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Gli occhi dell'uom cercan morendo | il Sole: e tutti l'ultimo sospiro | mandano i petti alla fuggente luce", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Già il dotto e il ricco ed il patrizio vulgo, | decoro e mente al bello italo regno, | nelle adulate reggie ha sepoltura | già vivo, e i stemmi unica laude.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Quel grande | che temprando lo scettro a' regnatori | gli allòr ne sfronda, ed alle genti svela | di che lagrime grondi e di che sangue", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "E tu prima, Firenze, udivi il carme | che allegrò l'ira al Ghibellin fuggiasco, | e tu i cari parenti e l'idïoma | dèsti a quel dolce di Calliope labbro | che Amore in Grecia nudo e nudo in Roma | d'un velo candidissimo adornando, | rendea nel grembo a Venere Celeste.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "E a questi marmi | venne spesso Vittorio ad ispirarsi, | irato a' patrii Numi; errava muto | ove Arno è più deserto, i campi e il cielo | desîoso mirando; e poi che nullo | vivente aspetto gli molcea la cura, | qui posava l'austero; e avea sul volto | il pallor della morte e la speranza. | Con questi grandi abita eterno: e l'ossa | fremono amor di patria.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "E me che i tempi ed il desio d'onore | fan per diversa gente ir fuggitivo, | me ad evocar gli eroi chiamin le Muse | del mortale pensiero animatrici. Siedon custodi de' sepolcri, e quando | il tempo con sue fredde ale vi spazza | fin le rovine, le Pimplèe fan lieti | di lor canto i deserti, e l'armonia | vince di mille secoli il silenzio.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "E tu onore di pianti, Ettore, avrai, | ove fia santo e lagrimato il sangue | per la patria versato, e finché il Sole | risplenderà su le sciagure umane.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "A rifare l'Italia bisogna disfare le sètte.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La guerra del Peloponneso ebbe principio dall'ingiusto eroismo di Pericle e de' suoi concittadini; e crudele progresso dalla stoltezza delle greche Città; e iniquo fine dagli Spartani, i quali se, come dovevano, avessero preservate le armi e le leggi delle greche Repubbliche, anziché abbandonarle a fazioni cittadinesche industriosamente corrotte, non avrebbero avvalorato la politica di Filippo, che poté impunemente poscia contaminare fin anche la religione de' giuramenti; e Sparta piegò con tutta la Grecia sotto a' Macedoni.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Il tempo, che in sé è indefinibile, si misura soltanto dagli avvenimenti, e quello è maggiore corso di tempo che mena seco più numerosi, più forti e più memorabili eventi.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "E il biasimo dietro le spalle è pure la buona cosa! si può profittarne senza essere obbligati, e l'amor proprio non è ferito.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "chi preferisce l'onore alla vita è padrone di tutti coloro che vogliono avvilirlo.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "facilmente si accusa d'indole violenta chi rispinge le ingiurie con coraggio; e chi si mostra generosamente qual è, dà il fianco alle ferite più di colui che si copre col manto dell'ipocrisia.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "questo so bene ch'io né per ripulse, né per favori, né per lodi né per biasimi mi rimoverò mai dal mio proponimento.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Si può bensì anche in mezzo alle ingiustizie sentirsi giusto, forte e libero; e la dignità dell'uomo si vendica più nel sopportare nobilmente, che nel lamentarsi e gridare invano.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La noja proviene o da debolissima coscienza dell'esistenza nostra, per cui non ci sentiamo capaci di agire, o da coscienza eccessiva, per cui vediamo di non poter agire quanto vorremmo.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La vita, pur troppo, non è che agitazione; agitazione alterna e perpetua, simile al pendolo d'un oriuolo: arrestato il pendolo, le ruote non si muovono più; spente le passioni, e le loro illusioni, non vi è più corda; le ore dell'uomo non progrediscono più, e l'assoluta tranquillità di ogni ente mortale comincia col silenzio, con l'oscurità, e si compie con l'eterna dissoluzione.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "L'arte non consiste nel rappresentare cose nuove, bensì nel rappresentare con novità.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La miseria è da fuggirsi, non la povertà: ed io vedo miseri ed indigenti, e perseguitati da' creditori, ed esulcerati da' bisogni quotidiani molti uomini tenuti ricchi, ma tranquilli ad un tempo; e onorati molti altri che hanno la saviezza e l'arte di spendere quel poco che possono senza intaccare l'altrui, quantunque il mondo li creda poveri, e li compianga talvolta, e spesso li fugga, perché non sono né protetti né protettori.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Per me stimo il danaro da più di tutte quelle cose che il danaro può dare, e da meno delle cose che il danaro non può dare, e che pure sono ottime a questa misera vita degli uomini.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "le sciocche e laide abitudini sono le corruzioni della nostra natura.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "una battaglia, per quanto sia prospera, dissangua anche il vincitore.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "le passioni passano, ma le sciagure restano perpetue nella nostra vita; e se non possiamo evitarle, non dobbiamo almeno esacerbarle co' nostri rimorsi, e renderle irremediabili.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "gli uomini sono pronti a ripigliarsi la stima che concedono, quando non la vedano alimentata da molte e perpetue prove di fatti.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "quando per giovar debolmente ad altri si corre rischio di nuocere gravemente a se stessi, l'intricarsene è pazzia da bastone", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Le particelle [...] in ogni idioma sono le vere e sole giunture delle idee principali del discorso: danno inoltre i toni i mezzitoni come nella musica; ed ajutano lo scrittore a quel chiaroscuro che tanto è più grato, quanto le minime tinte che lo distinguono spiccano meno.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "io credo fermamente che la grammatica s'abbia ad insegnare a chi sa practically la lingua. S'impara a combinare infinitamente prima su lo scacchiere, e poi sul libro; datemi il libro prima dello scacchiere, ed io diverrò dottore e ignorante ad un tempo: la teoria insomma deve nella lingua, come forse in tutte le discipline, succedere alla pratica, perché non s'hanno mai nozioni generali e quindi regole sicure, senza risalirvi per le particolari.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Sappi che la malignità, la cattiveria, e l'ignoranza sono bestie ferocissime perché sono codarde; e perché sono codarde s'avventano sopra il debole, e tremano dinanzi a chi si difende.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "l'umana prudenza prevede, ma non provvede.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "la malinconia, [...] dopo la noja, è la più vile infermità de' mortali; perché è infermità inoperosa, ingrata alla natura, freddissima nei desiderj, fantastica in tutto fuorché ad illudersi delle promesse della speranza.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "la maggiore e più stolta incoerenza si è quella di voler fare a modo del mondo, temendo più le sue opinioni, che i giudizj della nostra propria coscienza.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La Provvidenza non abbandona mai chi non abbandona se stesso.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "non v'è animale più invidioso del letterato", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "la natura ha creato il genere umano in perpetuo stato di guerra: mancano le armi, si corre alle ingiurie; manca il coraggio di ingiuriare francamente ed a viso aperto, e' si piglia la maschera dell'amicizia. Noi, per farci onore nel mondo e per tranquillare la nostra propria coscienza, ci fidiamo più sopra i vizj degli altri, che su le nostre proprie virtù.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "le accuse che si danno privatamente, e con l'orpello della compassione, sono le più credute, e fanno piaga insanabile", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "è meglio esser uomo senza danari, che l'aver danari senz'essere uomo.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "in tutte le cose v'è il male e il bene; basta saperli distinguere: rassegnarsi al male, e giovarsi del bene.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "non può essere mai che l'uomo giusto e compassionevole sia davvero infelice, e in tutti i guai la sua propria coscienza gli serve di consolazione e di usbergo.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "il disprezzare non è da tutti.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "la troppa età è data dal cielo in pena del desiderio di troppo vivere.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "il dissimulare nella vita umana riesce inevitabile spesso; e la necessità lo giustifica, perché chiunque non sa tacere o trovar espediente di nascondere il proprio secreto agli indagatori indiscreti si espone alla curiosità e alla malignità dei tristi, che non sono né inattivi, né in poco numero. Ma il simulare è altra cosa, perché la simulazione, è l'arte perfida di mostrare quello che è falso, affine di scoprire quello che è vero e impadronirsi dell'altrui secreto. Sì fatta arte nessuna necessità la giustifica", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "la lingua italiana non è stata mai parlata: è lingua scritta, e non altro; e perciò letteraria, e non popolare; – e se mai verrà giorno che le condizioni d'Italia la facciano lingua scritta insieme e parlata, e letteraria e popolare ad un tempo, allora le liti e i pedanti andranno al diavolo e dentro ai vortici del fiume Lete in anima e in corpo, e i letterati non somiglieranno più a' mandarini, e i dialetti non predomineranno nelle città capitali d'ogni provincia: la Nazione non sarà moltitudine di Chinesi, ma Popolo atto ad intender ciò che si scrive, e giudice di lingua e di stile", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Sdegno il verso che suona e che non crea.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Tre vaghissime donne a cui le trecce | infiora di felici itale rose | giovinezza, e per cui splende più bello | sul lor sembiante il giorno, all'ara vostra | sacerdotesse, o care Grazie, io guido.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Ma se danza, | vedila! tutta l'armonia del suono scorre dal suo bel corpo, e dal sorriso | della sua bocca; e un moto, un atto, un vezzo | manda agli sguardi venustà improvvisa.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Pari al numero lor volino gl'inni | alle vergini sante, armonïosi | del peregrino suono uno e diverso | di tre favelle. Intento odi, Canova; | ch'io mi veggio d'intorno errar l'incenso, | qual si spandea sull'are a' versi arcani | d'Anfïone: presente ecco il nitrito | de' corsieri dircèi; benché Ippocrene | li dissetasse, e li pascea dell'aure | Eolo, e prenunzia un'aquila volava, | e de' suoi freni li adornava il Sole, | pur que' vaganti Pindaro contenne | presso il Cefiso, ed adorò le Grazie.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Tornino i grandi | Occhi fatali al lor natio sorriso", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "E in te beltà rivive, | l'aurea beltate ond'ebbero | ristoro unico a' mali | le nate a vaneggiar menti mortali.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Fiorir sul caro viso | veggo la rosa; tornano | i grandi occhi al sorriso | insidïando", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Itale genti, se Virtù suo scudo / su voi non stende, Libertà vi nuoce", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "la vera sapienza consiste nel giovarsi di quelle poche verità che sono certissime a' sensi; perché o sono dedotte da una serie lunga di fatti, o sono sì pronte che non hanno bisogno di dimostrazioni scientifiche.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "a chi non ha patria non istà bene l'essere sacerdote, né padre.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Forse perché della fatal quïete | tu sei l'immago a me sì cara vieni | o Sera!", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "E mentre io guardo la tua pace, dorme | quello spirto guerrier ch'entro mi rugge.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Amor fra l'ombre inferne | seguirammi immortale, onnipotente.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Né più mai toccherò le sacre sponde | ove il mio corpo fanciulletto giacque, | Zacinto mia, che te specchi nell'onde | del greco mar da cui vergine nacque | Venere", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Colui che l'acque | cantò fatali", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "bello di fama e di sventura | baciò la sua petrosa Itaca Ulisse", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Tu non altro che il canto avrai del figlio, | o materna mia terra, a noi prescrisse | il fato illacrimata sepoltura.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Un dì, s'io non andrò sempre fuggendo | di gente in gente, me vedrai seduto | su la tua pietra, o fratel mio, gemendo | il fior de' tuoi gentili anni caduto.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Breve è la vita, e lunga è l'arte.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Il sacrificio della patria nostra è consumato: tutto è perduto; e la vita, seppure ne verrà concessa, non ci resterà che per piangere le nostre sciagure, e la nostra infamia. Il mio nome è nella lista di proscrizione, lo so; ma vuoi tu ch'io per salvarmi da chi m'opprime mi commetta a chi mi ha tradito? Consola mia madre: vinto dalle sue lagrime le ho ubbidito, e ho lasciato Venezia per evitare le prime persecuzioni, e le più feroci. Or dovrò io abbandonare anche questa mia solitudine antica, dove, senza perdere dagli occhi il mio sciagurato paese, posso ancora sperare qualche giorno di pace? Tu mi fai raccapricciare, Lorenzo: quanti sono dunque gli sventurati? E noi, pur troppo, noi stessi Italiani ci laviamo le mani nel sangue degl'Italiani. Per me segua che può. Poiché ho disperato e della mia patria e di me, aspetto tranquillamente la prigione e la morte. Il mio cadavere almeno non cadrà fra braccia straniere; il mio nome sarà sommessamente compianto da' pochi uomini buoni, compagni delle nostre miserie; e le mie ossa poseranno su la terra de' miei padri.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Che è mai l'uomo? Il coraggio fu sempre dominatore dell'universo perché tutto è debolezza e paura.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Gli amori della moltitudine sono brevi ed infausti; giudica, più che dall'intento, dalla fortuna; chiama virtù il delitto utile, e scelleraggine l'onestà che le pare dannosa; e per avere i suoi plausi conviene o atterrirla, o ingrassarla, e ingannarla sempre.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Il coraggio non deve dare diritto per opprimere il debole.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La fama degli eroi spetta un quarto alla loro audacia; due quarti alla sorte, e l'altro quarto, ai loro delitti. Pur se ti reputi bastevolmente fortunato e crudele per aspirare a questa gloria, pensi tu che i tempi te ne porgano i mezzi?", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La Natura siede qui solitaria e minacciosa, e caccia da questo suo regno tutti i viventi.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Noi chiamiamo pomposamente virtù tutte quelle azioni che giovano alla sicurezza di chi comanda e alla paura di chi serve.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Sciagurati coloro che, per non essere scellerati, hanno bisogno della religione.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Se gli uomini si conducessero sempre al fianco la morte, non servirebbero sì vilmente.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "La Ragione? – è come il vento; ammorza le faci, ed anima gl'incendj.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Ma gli onori e la tranquillità del mio secolo guasto meritano forse di essere acquistati col sacrificio dell'anima? Forse più che l'amore della virtù, il timore della bassezza m'ha rattenuto alle volte da quelle colpe, che sono rispettate ne' potenti, tollerate ne' più ma che, per non lasciare senza vittime il simulacro della giustizia, sono punite nei miseri.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Ma io moro incontaminato, e padrone di me stesso, e pieno di te, e certo del tuo pianto! Perdonami, Teresa, se mai – ah consolati, e vivi per la felicità de' nostri miseri genitori; la tua morte farebbe maledire le mie ceneri. Che se taluno ardisse incolparti del mio infelice destino, confondilo con questo mio giuramento solenne ch'io pronunzio gittandomi nella notte della morte: Teresa è innocente. – Ora tu accogli l'anima mia.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Credo che il desiderio di sapere e ridire la storia de' tempi andati sia figlio del nostro amor proprio che vorrebbe illudersi e prolungare la vita unendoci agli uomini ed alle cose che non sono più, e facendole, sto per dire, di nostra proprietà. Ama la immaginazione di spaziare fra i secoli e di possedere un altro universo.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Io non odio persona al mondo, ma vi sono cert'uomini ch'io ho bisogno di vedere soltanto da lontano.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Cos'è l'uomo se tu lo abbandoni alla sola ragione fredda, calcolatrice? scellerato, e scellerato bassamente.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Non sono felice! mi disse Teresa; e con questa parola mi strappò il cuore.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Facciamo tesoro di sentimenti cari e soavi i quali ci ridestino per tutti gli anni, che ancora forse tristi e perseguitati ci avanzano, la memoria che non siamo sempre vissuti nel dolore.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Pare a te, mio Lorenzo, che se l'avversità ci riducesse a domandare del pane, vi sarebbe taluno memore delle sue promesse? o nessuno, o qualche astuto soltanto, che co' suoi beneficj vorrebbe comperare il nostro avvilimento. Amici da bonaccia, nelle burrasche ti annegano. Per costoro tutto è calcolo in fondo. Onde se v'ha taluno nelle cui viscere fremano le generose passioni, o le deve strozzare, o rifuggirsi come le aquile e le fiere magnanime ne' monti inaccessibili e nelle foreste lungi dalla invidia e dalla vendetta degli uomini. Le sublimi anime passeggiano sopra le teste della moltitudine che oltraggiata dalla loro grandezza tenta d'incatenarle o di deriderle, e chiama pazzie le azioni ch'essa immersa nel fango non può, non che ammirare, conoscere. – Io non parlo di me; ma quand'io ripenso agli ostacoli che frappone la società al genio ed al cuore dell'uomo, e come ne' governi licenziosi o tirannici tutto è briga, interesse e calunnia – io m'inginocchio a ringraziar la Natura che dotandomi di questa indole nemica di ogni servitù, mi ha fatto vincere la fortuna e mi ha insegnato a innalzarmi sopra la mia educazione. So che la prima, sola, vera scienza è questa dell'uomo la quale non si può studiare nella solitudine, e ne' libri: e so che ognuno dee prevalersi della propria fortuna, o dell'altrui per camminare con qualche sostegno su i precipizj della vita.", Author = "Ugo Foscolo" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ugo_Foscolo", Text = "Sai tu perché fra la turba de' dotti gli uomini sommi son così rari? Quello istinto ispirato dall'alto che costituisce il genio non vive se non se nella indipendenza e nella solitudine, quando i tempi vietandogli d'operare, non gli lasciano che lo scrivere. Nella società si legge molto, non si medita, e si copia; parlando sempre, si svapora quella bile generosa che fa sentire, pensare, e scrivere fortemente: per balbettar molte lingue, si balbetta anche la propria, ridicoli a un tempo agli stranieri e a noi stessi: dipendenti dagl'interessi, dai pregiudizj, e dai vizj degli uomini fra' quali si vive, e guidati da una catena di doveri e di bisogni, si commette alla moltitudine la nostra gloria, e la nostra felicità: si palpa la ricchezza e la possanza, e si paventa perfino di essere grandi perché la fama aizza i persecutori, e l'altezza di animo fa sospettare i governi; e i principi vogliono gli uomini tali da riescire né eroi, né incliti scellerati mai.", Author = "Ugo Foscolo" },
        };
    }
}